  --hairline: rgb(155 176 196 / 0.16);
  --ink-hi: #e6eef7;
  --ink-mid: #9bb0c4;
  --ink-low: #61758a; /* 18px+ or non-essential text only */
  --flash: #9fe3ff; /* live: tonight */
  --afterglow: #ffb347; /* memory: past flights and matches */
  --bone: #e8e2d4; /* forecasts, always dotted */
  --alert: #ff5a5f;
  --verified: #6ee7a8;
  --font-ui: "B612", system-ui, sans-serif;
  --font-data: "B612 Mono", ui-monospace, monospace;
  --dur-micro: 120ms;
  --dur-panel: 240ms;
  --dur-reveal: 600ms;
  --dur-cinema: 1200ms;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-inout: cubic-bezier(0.65, 0, 0.35, 1);
}

@theme {
  --color-*: initial;
  --shadow-*: initial;
  --drop-shadow-*: initial;
  --inset-shadow-*: initial;
  --ease-*: initial;
  --text-*: initial;
  --radius-*: initial;
  --blur-*: initial;

  /* Type scale (§17.1): 12, 13, 15, 18, 24, 32 px */
  --text-12: 12px;
  --text-13: 13px;
  --text-15: 15px;
  --text-18: 18px;
  --text-24: 24px;
  --text-32: 32px;

  /* Radii by hierarchy (§17.1): theater 0, panels 6, buttons 4, chips fully rounded */
  --radius-panel: 6px;
  --radius-button: 4px;
  --radius-chip: 9999px;

  --blur-glass: 14px;
}

