  await expect
    .poll(async () => Math.max(...(await blocks.evaluateAll((bs) => bs.map((b) => Number(b.getAttribute("data-seq")))))))
    .toBeGreaterThan(seed);
  await expect(page.getByTestId("ledger-verified")).toContainText("verified");
});

