from pathlib import Path
p = Path("src/three/Label.tsx"); s = p.read_text()
s = s.replace('import { type Group, type PerspectiveCamera, Vector3 } from "three";', 'import { type Group, MeshBasicMaterial, type PerspectiveCamera, Vector3 } from "three";')
s = s.replace('const tmp = new Vector3();', '''const tmp = new Vector3();

/**
 * The base material every label derives from. troika derives its text (and outline) materials
 * from the base by prototype, so depth settings must live here: a `material-depthTest` prop only
 * reaches the fill, and the labels were then cut by the grid and the asset boxes.
 */
const LABEL_BASE = new MeshBasicMaterial({
  transparent: true,
  depthTest: false,
  depthWrite: false,
  toneMapped: false,
});''')
s = s.replace('''        renderOrder={10}
        material-depthTest={false}
        material-depthWrite={false}
      >''', '''        renderOrder={10}
        material={LABEL_BASE}
      >''')
p.write_text(s)
p = Path("src/three/Ground.tsx"); s = p.read_text()
s = s.replace('import { Grid } from "@react-three/drei";', 'import { Grid } from "@react-three/drei";\nimport { useLayoutEffect, useRef } from "react";\nimport type { Mesh, Material } from "three";')
s = s.replace('''export function Ground() {
  return (
    <Grid''', '''export function Ground() {
  const ref = useRef<Mesh>(null);
  useLayoutEffect(() => {
    // drei's grid writes depth: lines lying on the ground (fence, roads, rings) then lose the depth
    // test against it far from the camera and show as dashes
    const m = ref.current?.material as Material | undefined;
    if (m) m.depthWrite = false;
  }, []);
  return (
    <Grid
      ref={ref}''')
p.write_text(s)
p = Path("src/three/Installation.tsx"); s = p.read_text()
s = s.replace('''      <Label text={assetLabel(a.kind)} position={[cx, h + 12, cz]} px={12} tone="--ink-hi" />''', '''      {/* under the footprint: the drone and its tag fly above, so they do not collide */}
      <Label
        text={assetLabel(a.kind)}
        position={[cx, 0, cz]}
        px={12}
        tone="--ink-hi"
        anchorY="top"
        dyPx={-6}
      />''')
p.write_text(s)
p = Path("src/three/Drone.tsx"); s = p.read_text()
s = s.replace('''          text="No Remote ID"
          position={[0, 0, 0]}
          px={12}
          tone="--alert"
          anchorX="left"
          anchorY="middle"
          dxPx={18}''', '''          text="No Remote ID"
          position={[0, 0, 0]}
          px={12}
          tone="--alert"
          anchorX="center"
          anchorY="bottom"
          dyPx={16}''')
p.write_text(s)
EOF
